/**
 * @name Path traversal in file operations
 * @description User-controlled data reaching file path operations can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability from $@.", source.getNode(), "user input"

/**
 * @name Path traversal in multipart file uploads
 * @description User input flows into file operations in multipart handling
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal-multipart
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module MultipartTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for file system operations in multipart handling
    exists(API::CallNode call |
      call = API::moduleImport("aiohttp").getMember("multipart").getMember(["MultipartReader", "BodyPartReader"]).getACall() and
      sink = call.getArg(0)
    ) or
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module MultipartTraversalFlow = TaintTracking::Global<MultipartTraversalConfig>;
import MultipartTraversalFlow::PathGraph

from MultipartTraversalFlow::PathNode source, MultipartTraversalFlow::PathNode sink
where MultipartTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal in multipart handling from $@.", source.getNode(), "user input"

/**
 * @name Server-Side Request Forgery (SSRF) in aiohttp client
 * @description User input flows into client request URLs without validation
 * @kind path-problem
 * @problem.severity error
 * @id py/ssrf-aiohttp-client
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module SsrfConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      // Check for aiohttp client request methods
      (call = API::moduleImport("aiohttp").getMember("client").getMember(["get", "post", "put", "delete", "patch", "head", "options"]).getACall() or
       call = API::moduleImport("aiohttp").getMember("ClientSession").getMember(["get", "post", "put", "delete", "patch", "head", "options"]).getACall() or
       call = API::moduleImport("aiohttp").getMember("client").getMember("request").getACall()) and
      // First argument is typically the URL
      sink = call.getArg(0)
    )
  }
}

module SsrfFlow = TaintTracking::Global<SsrfConfig>;
import SsrfFlow::PathGraph

from SsrfFlow::PathNode source, SsrfFlow::PathNode sink
where SsrfFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SSRF vulnerability in aiohttp client from $@.", source.getNode(), "user input"

/**
 * @name WebSocket injection vulnerabilities
 * @description Untrusted data flowing into WebSocket operations
 * @kind path-problem
 * @problem.severity error
 * @id py/websocket-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module WebSocketConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      // WebSocket send/receive operations
      (call = API::moduleImport("aiohttp").getMember("web_ws").getMember(["send_str", "send_bytes", "send_json"]).getACall() or
       call = API::moduleImport("aiohttp").getMember("client_ws").getMember(["send_str", "send_bytes", "send_json"]).getACall()) and
      sink = call.getArg(0)
    )
  }
}

module WebSocketFlow = TaintTracking::Global<WebSocketConfig>;
import WebSocketFlow::PathGraph

from WebSocketFlow::PathNode source, WebSocketFlow::PathNode sink
where WebSocketFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "WebSocket injection vulnerability from $@.", source.getNode(), "user input"
